var RELCAL_CONTEUDO_MODULO='<style>\n#tplRelCalContainer {\n  color-scheme: light;\n  --bg: var(--bc-bg);\n  --bg-2: var(--bc-surface-3);\n  --card: var(--bc-surface);\n  --panel: var(--bc-surface);\n  --panel-2: var(--bc-surface-2);\n  --input: #FFFFFF;\n  --input-hover: var(--bc-surface-2);\n  --text: var(--bc-text);\n  --text-strong: var(--bc-text);\n  --muted: var(--bc-text-3);\n  --muted-2: var(--bc-text-3);\n  --border: var(--bc-line);\n  --border-strong: var(--bc-line-2);\n  --accent: var(--bc-action);\n  --accent-2: var(--bc-action);\n  --success-bg: var(--bc-action-bg);\n  --info-bg: var(--bc-info-bg);\n  --warning-bg: var(--bc-warn-bg);\n  --danger-bg: var(--bc-danger-bg);\n  --shadow-soft: none;\n  --radius: 6px;\n  --radius-sm: 4px;\n  --transition: 0.16s ease;\n}\n\n#tplRelCalContainer * { box-sizing: border-box; }\n#tplRelCalContainer .hidden { display: none !important; }\n#tplRelCalContainer, #tplRelCalContainer body {\n  font-family: var(--bc-sans);\n  background: transparent !important;\n  color: var(--text) !important;\n}\n\n#tplRelCalContainer .wrap { max-width: 1100px; margin: 0 auto; padding: 18px; }\n\n#tplRelCalContainer .header-card {\n  background: #FFFFFF !important;\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 14px 18px;\n  box-shadow: var(--shadow-soft);\n  margin-bottom: 14px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 14px;\n}\n\n#tplRelCalContainer .brand { display: flex; align-items: center; gap: 16px; min-width: 0; flex: 1; }\n#tplRelCalContainer .title-area h1 { margin: 0; font-size: 19px; color: var(--text-strong); font-weight: 800; line-height: 1.2; }\n#tplRelCalContainer .title-area p { margin: 5px 0 0; color: var(--muted); font-size: 13px; line-height: 1.45; }\n\n#tplRelCalContainer .status-badge {\n  background: var(--success-bg) !important;\n  color: var(--bc-text-2) !important;\n  border: 1px solid var(--bc-action-line);\n  padding: 7px 12px;\n  border-radius: 999px;\n  font-weight: 800;\n  font-size: 12px;\n  white-space: nowrap;\n}\n#tplRelCalContainer .status-badge.is-danger { background: var(--danger-bg) !important; color: var(--bc-danger) !important; border-color: var(--bc-danger-line); }\n#tplRelCalContainer .status-badge.is-neutral { background: var(--bc-surface-3) !important; color: var(--bc-text-2) !important; border-color: var(--bc-line); }\n\n#tplRelCalContainer .panel {\n  background: #FFFFFF !important;\n  border-radius: var(--radius);\n  padding: 18px;\n  box-shadow: var(--shadow-soft);\n  border: 1px solid var(--border);\n  margin-bottom: 14px;\n}\n\n#tplRelCalContainer .panel h2 {\n  margin: 0 0 16px;\n  font-size: 14px;\n  color: var(--text-strong) !important;\n  border-bottom: 1px solid var(--border);\n  padding-bottom: 11px;\n  text-transform: uppercase;\n}\n#tplRelCalContainer .panel h2::before {\n  content: "";\n  display: inline-block;\n  width: 8px;\n  height: 8px;\n  margin-right: 9px;\n  border-radius: 50%;\n  background: var(--bc-info);\n  vertical-align: 1px;\n}\n\n#tplRelCalContainer .section-divider {\n  margin: 22px 0 14px;\n  padding: 8px 10px;\n  border: 1px solid var(--border);\n  border-left: 3px solid var(--bc-line-2);\n  background: transparent !important;\n  border-radius: 6px;\n  font-size: 12px;\n  font-weight: 800;\n  color: var(--bc-text);\n  text-transform: uppercase;\n}\n\n#tplRelCalContainer .form-row { display: flex; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }\n#tplRelCalContainer .form-group { flex: 1; min-width: 205px; }\n#tplRelCalContainer .form-group.w-100 { flex: 1 1 100%; }\n#tplRelCalContainer .form-group label { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 700; color: var(--bc-text-2); }\n#tplRelCalContainer .field-help { display: block; margin-top: 6px; font-size: 11px; color: var(--muted-2); line-height: 1.45; }\n\n#tplRelCalContainer .form-control {\n  width: 100%;\n  min-height: 42px;\n  padding: 10px 11px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  font-size: 13px;\n  color: var(--text-strong) !important;\n  background: var(--input) !important;\n}\n#tplRelCalContainer .form-control:hover { background: var(--input-hover) !important; border-color: var(--border-strong); }\n#tplRelCalContainer .form-control:focus { outline: none; border-color: var(--accent-2); box-shadow: 0 0 0 3px transparent; }\n#tplRelCalContainer select.form-control { cursor: pointer; }\n\n#tplRelCalContainer .check-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(118px, 1fr)); gap: 8px; margin-top: 6px; }\n#tplRelCalContainer .check-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: #FFFFFF;\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 9px 10px;\n  font-size: 12px;\n  color: var(--bc-text);\n}\n#tplRelCalContainer .check-item input[type="checkbox"] {\n  width: 16px; height: 16px; min-height: 0; flex: 0 0 auto;\n  accent-color: var(--accent);\n  cursor: pointer;\n}\n#tplRelCalContainer .check-grid-multiarquivo { grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }\n#tplRelCalContainer .check-item-com-import { flex-wrap: wrap; align-items: flex-start; }\n\n#tplRelCalContainer .lista-documentos-salvos { list-style: none; padding: 0; margin: 8px 0 0; }\n#tplRelCalContainer .lista-documentos-salvos li { padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px; margin-bottom: 6px; font-size: 12px; }\n#tplRelCalContainer .lista-documentos-salvos a { color: var(--accent-2); }\n\n#tplRelCalContainer .btn-container { display: flex; gap: 10px; margin-top: 22px; flex-wrap: wrap; }\n#tplRelCalContainer .btn {\n  padding: 11px 16px;\n  border: 1px solid transparent;\n  border-radius: var(--radius-sm);\n  font-weight: 800;\n  font-size: 13px;\n  cursor: pointer;\n  min-height: 42px;\n}\n#tplRelCalContainer .btn:disabled { opacity: 0.62; cursor: not-allowed; }\n#tplRelCalContainer .btn-primary { background: var(--bc-action) !important; border-color: var(--bc-brand) !important; color: #FFFFFF !important; }\n#tplRelCalContainer .btn-secondary { background: #FFFFFF !important; border: 1px solid var(--bc-line-2) !important; color: var(--bc-text) !important; }\n#tplRelCalContainer .btn-secondary:hover:not(:disabled) { background: var(--bc-surface-2) !important; }\n\n#tplRelCalContainer .alert-box { margin-top: 14px; border-radius: var(--radius-sm); padding: 13px 14px; font-size: 13px; line-height: 1.55; border: 1px solid transparent; }\n#tplRelCalContainer .alert-box.success { background: var(--success-bg) !important; color: var(--bc-text-2) !important; border-color: var(--bc-action-line); }\n#tplRelCalContainer .alert-box.error { background: var(--danger-bg) !important; color: var(--bc-danger) !important; border-color: var(--bc-danger-line); }\n\n@media (max-width: 768px) {\n  #tplRelCalContainer .wrap { padding: 10px; }\n  #tplRelCalContainer .panel { padding: 14px; }\n  #tplRelCalContainer .header-card { padding: 14px; }\n  #tplRelCalContainer .brand { width: 100%; flex-direction: column; align-items: flex-start; gap: 10px; }\n  #tplRelCalContainer .btn { width: 100%; }\n  #tplRelCalContainer .btn-container { flex-direction: column; }\n}\n\n#tplRelCalContainer .manual-wrap {\n      max-width: 900px;\n      margin: 0 auto;\n      padding: 18px 18px 60px;\n      line-height: 1.6;\n    }\n    #tplRelCalContainer .manual-wrap h1 { font-size: 26px; margin-bottom: 4px; }\n    #tplRelCalContainer .manual-wrap .subtitulo { color: var(--muted); margin-top: 0; margin-bottom: 22px; }\n    #tplRelCalContainer .manual-wrap h2 {\n      font-size: 19px;\n      margin-top: 40px;\n      padding-bottom: 8px;\n      border-bottom: 1px solid var(--border);\n      color: var(--text-strong);\n    }\n    #tplRelCalContainer .manual-wrap h3 { font-size: 15px; margin-top: 26px; color: var(--accent-2); }\n    #tplRelCalContainer .manual-wrap p { color: var(--text); }\n    #tplRelCalContainer .manual-wrap table {\n      width: 100%;\n      border-collapse: collapse;\n      margin: 14px 0 22px;\n      font-size: 13.5px;\n    }\n    #tplRelCalContainer .manual-wrap th, #tplRelCalContainer .manual-wrap td {\n      border: 1px solid var(--border);\n      padding: 8px 10px;\n      text-align: left;\n      vertical-align: top;\n    }\n    #tplRelCalContainer .manual-wrap th {\n      background: var(--panel-soft, var(--panel));\n      color: var(--text-strong);\n      white-space: nowrap;\n    }\n    #tplRelCalContainer .manual-wrap tr:nth-child(even) td { background: var(--bc-surface-2); }\n    #tplRelCalContainer .manual-wrap td:first-child, #tplRelCalContainer .manual-wrap th:first-child { white-space: nowrap; }\n    #tplRelCalContainer .callout {\n      background: var(--bc-action-bg);\n      border: 1px solid var(--bc-action-line);\n      border-left: 4px solid var(--accent);\n      border-radius: var(--radius-sm);\n      padding: 12px 14px;\n      margin: 14px 0;\n      font-size: 13.5px;\n    }\n    #tplRelCalContainer .callout strong { color: var(--text-strong); }\n    #tplRelCalContainer .manual-wrap ol, #tplRelCalContainer .manual-wrap ul { padding-left: 22px; }\n    #tplRelCalContainer .manual-wrap ol li, #tplRelCalContainer .manual-wrap ul li { margin-bottom: 6px; }\n    #tplRelCalContainer .toc {\n      background: var(--panel);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      padding: 16px 20px;\n      margin-bottom: 30px;\n    }\n    #tplRelCalContainer .toc h2 { margin-top: 0; border-bottom: none; font-size: 15px; }\n    #tplRelCalContainer .toc ol { columns: 2; column-gap: 30px; }\n    #tplRelCalContainer .toc a { text-decoration: none; }\n    #tplRelCalContainer .toc a:hover { text-decoration: underline; }\n    #tplRelCalContainer .voltar-topo {\n      position: fixed;\n      right: 24px;\n      bottom: 24px;\n      z-index: 30;\n    }\n    #tplRelCalContainer code.campo { background: var(--input); border: 1px solid var(--border); border-radius: 4px; padding: 1px 6px; font-family: var(--bc-mono); font-size: 12.5px; color: var(--accent-2); }\n\n#tplRelCalContainer .terminal-wrap { margin-top: 12px; border-radius: var(--radius-sm); overflow: hidden; border: 1px solid var(--border); box-shadow: inset 0 1px 0 rgba(255,255,255,.02); }\n#tplRelCalContainer .terminal-header { background: #FFFFFF; color: var(--bc-text-3); padding: 10px 12px; font-size: 11px; font-weight: 800; border-bottom: 1px solid var(--border); }\n#tplRelCalContainer .terminal { background: #FFFFFF; color: var(--bc-action); padding: 14px; font-family: var(--bc-mono); font-size: 12px; height: 260px; overflow-y: auto; white-space: pre-wrap; line-height: 1.55; }\n#tplRelCalContainer .terminal .success { color: var(--bc-action); font-weight: 800; }\n#tplRelCalContainer .terminal .error { color: var(--bc-danger); font-weight: 800; }\n#tplRelCalContainer .terminal .warn { color: var(--bc-warn); font-weight: 800; }\n</style>\n<script>\n  let RELCAL_CFG_CLIENTE = null;\n\n  function tplRelCal_writeLog(text, tipo) {\n    const term = document.getElementById(\'tplRelCal_terminalLog\');\n    if (!term) return;\n    const time = new Date().toLocaleTimeString(\'pt-BR\');\n    const line = document.createElement(\'div\');\n    line.textContent = \'[\' + time + \'] \\u2794 \' + String(text || \'\');\n    if (tipo === \'SUCESSO\') line.className = \'success\';\n    else if (tipo === \'ERRO\') line.className = \'error\';\n    else if (tipo === \'AVISO\') line.className = \'warn\';\n    term.appendChild(line);\n    term.scrollTop = term.scrollHeight;\n  }\n\n  function tplRelCal_limparLog() {\n    const term = document.getElementById(\'tplRelCal_terminalLog\');\n    if (term) term.innerHTML = \'\';\n    tplRelCal_writeLog(\'Histórico limpo.\', \'SUCESSO\');\n  }\n  let RELCAL_ULTIMO_HTML = null;\n  let RELCAL_VINC_ULTIMO_NOME_ = "";\n  let RELCAL_VINC_ULTIMO_URL_ = "";\n  // Congelados no momento em que o relatório é gerado (ver\n  // tplRelCal_gerarRelatorio) — "Salvar na pasta do cliente" usa estes valores\n  // em vez de reler o formulário ao vivo, porque o formulário é limpo\n  // logo depois de gerar (ver tplRelCal_prepararProximoRelatorio_).\n  let RELCAL_ULTIMO_CLIENTE = "";\n  let RELCAL_ULTIMO_TAG = "";\n  let RELCAL_ULTIMO_INSTRUMENTO_LABEL = "";\n\n  function tplRelCal_setStatusBadge(texto, variante) {\n    const el = document.getElementById(\'tplRelCal_statusBadge\');\n    if (!el) return;\n    el.textContent = texto;\n    el.className = \'status-badge\' + (variante ? (\' \' + variante) : \'\');\n  }\n\n  function tplRelCal_mostrarErro(container, err) {\n    const msg = (err && err.message) ? err.message : String(err);\n    const el = document.getElementById(container);\n    if (el) el.innerHTML = \'<div class="alert-box error">\' + msg + \'</div>\';\n  }\n\n  function tplRelCal_chamarApi(fn, payload) {\n    return new Promise(function(resolve, reject) {\n      SGO_iniciarCarregamento_();\n      google.script.run\n        .withSuccessHandler(function(res) { SGO_finalizarCarregamento_(); resolve(res); })\n        .withFailureHandler(function(err) { SGO_finalizarCarregamento_(); reject(err); })\n        .RelCal_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n    });\n  }\n\n  function tplRelCal_lerArquivoComoBase64_(inputEl) {\n    return new Promise(function(resolve) {\n      const file = inputEl && inputEl.files ? inputEl.files[0] : null;\n      if (!file) { resolve(null); return; }\n      const reader = new FileReader();\n      reader.onload = function(e) {\n        const resultado = String((e && e.target && e.target.result) || \'\');\n        const base64 = resultado.split(\',\')[1] || \'\';\n        resolve(base64 ? { base64: base64, mimeType: file.type || \'image/jpeg\' } : null);\n      };\n      reader.onerror = function() { resolve(null); };\n      reader.readAsDataURL(file);\n    });\n  }\n\n  function tplRelCal_renderFotosSlots_(containerId, prefixo, quantidade) {\n    const grid = document.getElementById(containerId);\n    if (!grid) return;\n    grid.innerHTML = \'\';\n    for (let i = 1; i <= quantidade; i++) {\n      const div = document.createElement(\'div\');\n      div.className = \'check-item check-item-com-import\';\n      div.innerHTML =\n        \'<label for="\' + prefixo + i + \'" style="margin:0;">Foto \' + i + \'</label>\' +\n        \'<input type="file" id="\' + prefixo + i + \'" class="form-control" accept="image/*" style="padding:6px;margin-top:4px;">\' +\n        \'<input type="text" id="\' + prefixo + i + \'Legenda" class="form-control" placeholder="Legenda da foto \' + i + \' (opcional)">\';\n      grid.appendChild(div);\n    }\n  }\n\n  function tplRelCal_coletarFotos_(prefixo, quantidade) {\n    const indices = [];\n    for (let i = 1; i <= quantidade; i++) indices.push(i);\n    const leituras = indices.map(function(i) {\n      return tplRelCal_lerArquivoComoBase64_(document.getElementById(prefixo + i)).then(function(foto) {\n        if (!foto) return null;\n        const legEl = document.getElementById(prefixo + i + \'Legenda\');\n        foto.legenda = legEl ? legEl.value : \'\';\n        return foto;\n      });\n    });\n    return Promise.all(leituras).then(function(fotos) { return fotos.filter(function(f) { return f; }); });\n  }\n\n  let RELCAL_ITENS_CALIBRAVEIS_ATUAL = [];\n\n  function tplRelCal_renderCertificadoSlots_(itensCalibraveis) {\n    const grid = document.getElementById(\'tplRelCal_certificadosGrid\');\n    if (!grid) return;\n    const itens = (itensCalibraveis && itensCalibraveis.length)\n      ? itensCalibraveis\n      : [{ codigo: \'INSTRUMENTO\', label: \'Certificado de Calibração\' }];\n    RELCAL_ITENS_CALIBRAVEIS_ATUAL = itens;\n\n    grid.innerHTML = \'\';\n    itens.forEach(function(item, indice) {\n      const div = document.createElement(\'div\');\n      div.className = \'check-item check-item-com-import\';\n      div.innerHTML =\n        \'<label for="tplRelCal_cert_\' + item.codigo + \'" style="margin:0;">\' + item.label + \'</label>\' +\n        \'<input type="file" id="tplRelCal_cert_\' + item.codigo + \'" class="form-control" \' +\n        \'accept="image/*,application/pdf" style="padding:6px;margin-top:4px;" \' +\n        \'onchange="tplRelCal_aoAnexarCertificado(\\\'\' + item.codigo + \'\\\')">\';\n      grid.appendChild(div);\n    });\n\n    const help = document.getElementById(\'tplRelCal_helpMultiCert\');\n    if (help) help.classList.toggle(\'hidden\', itens.length <= 1);\n    const statusEl = document.getElementById(\'tplRelCal_statusDeteccao\');\n    if (statusEl) statusEl.innerHTML = \'\';\n  }\n\n  function tplRelCal_coletarCertificados_() {\n    const leituras = RELCAL_ITENS_CALIBRAVEIS_ATUAL.map(function(item) {\n      const inputEl = document.getElementById(\'tplRelCal_cert_\' + item.codigo);\n      return tplRelCal_lerArquivoComoBase64_(inputEl).then(function(arquivo) {\n        if (!arquivo) return { codigo: item.codigo };\n        return { codigo: item.codigo, base64: arquivo.base64, mimeType: arquivo.mimeType };\n      });\n    });\n    return Promise.all(leituras);\n  }\n\n  function tplRelCal_aoTrocarInstrumento() {\n    const sel = document.getElementById(\'tplRelCal_instrumento\');\n    const chave = sel ? sel.value : \'\';\n    const info = (RELCAL_CFG_CLIENTE && RELCAL_CFG_CLIENTE.instrumentos) ? RELCAL_CFG_CLIENTE.instrumentos[chave] : null;\n    tplRelCal_renderCertificadoSlots_(info ? info.itensCalibraveis : []);\n  }\n\n  function tplRelCal_buscarCnpj() {\n    const cnpj = document.getElementById(\'tplRelCal_cnpj\').value;\n    tplRelCal_writeLog(\'Consultando CNPJ em base pública...\', \'SUCESSO\');\n    tplRelCal_chamarApi(\'apiConsultarCnpj\', { cnpj: cnpj }).then(function(res) {\n      document.getElementById(\'tplRelCal_cliente\').value = res.cliente || \'\';\n      document.getElementById(\'tplRelCal_endereco\').value = res.endereco || \'\';\n      tplRelCal_writeLog(\'CNPJ preenchido automaticamente: \' + (res.cliente || \'-\'), \'SUCESSO\');\n    }).catch(function(err) {\n      tplRelCal_writeLog(\'Falha ao consultar CNPJ: \' + ((err && err.message) ? err.message : err), \'ERRO\');\n      tplRelCal_mostrarErro(\'tplRelCal_statusArea\', err);\n    });\n  }\n\n  function tplRelCal_aoAnexarCertificado(codigo) {\n    const checkbox = document.getElementById(\'tplRelCal_detectarAuto\');\n    const certInput = document.getElementById(\'tplRelCal_cert_\' + codigo);\n    const statusEl = document.getElementById(\'tplRelCal_statusDeteccao\');\n    if (!checkbox || !checkbox.checked || !certInput || !certInput.files || !certInput.files[0]) {\n      if (statusEl) statusEl.innerHTML = \'\';\n      return;\n    }\n\n    if (statusEl) statusEl.innerHTML = \'<div class="field-help">Detectando dados do certificado automaticamente...</div>\';\n    tplRelCal_writeLog(\'Lendo certificado e detectando dados automaticamente...\', \'SUCESSO\');\n\n    const arquivoSelecionado = certInput.files[0];\n    const instrumentoSelecionado = document.getElementById(\'tplRelCal_instrumento\').value;\n    function deteccaoAindaAtual() {\n      return document.getElementById(\'tplRelCal_cert_\' + codigo) === certInput &&\n        certInput.files && certInput.files[0] === arquivoSelecionado &&\n        document.getElementById(\'tplRelCal_instrumento\').value === instrumentoSelecionado;\n    }\n    tplRelCal_lerArquivoComoBase64_(certInput).then(function(arquivo) {\n      if (!arquivo || !deteccaoAindaAtual()) return null;\n      return tplRelCal_chamarApi(\'apiDetectarCampos\', { certificado: arquivo });\n    }).then(function(res) {\n      if (!deteccaoAindaAtual()) return;\n      if (!res || !res.campos) {\n        if (statusEl) statusEl.innerHTML = \'<div class="field-help">Não foi possível detectar os dados automaticamente — preencha manualmente.</div>\';\n        tplRelCal_writeLog(\'Não foi possível detectar os dados do certificado automaticamente.\', \'AVISO\');\n        return;\n      }\n      const c = res.campos;\n      function preencherSeVazio(id, valor) {\n        const el = document.getElementById(id);\n        if (el && valor && !el.value) el.value = valor;\n      }\n      preencherSeVazio(\'tplRelCal_cliente\', c.cliente);\n      preencherSeVazio(\'tplRelCal_endereco\', c.endereco);\n      preencherSeVazio(\'tplRelCal_tag\', c.tag);\n      preencherSeVazio(\'tplRelCal_marca\', c.marca);\n      preencherSeVazio(\'tplRelCal_modelo\', c.modelo);\n      preencherSeVazio(\'tplRelCal_localizacao\', c.localizacao);\n      preencherSeVazio(\'tplRelCal_numeroDocumento\', c.numeroCertificado);\n      preencherSeVazio(\'tplRelCal_dataCalibracao\', c.dataCalibracao);\n      preencherSeVazio(\'tplRelCal_tecnicoResponsavel\', c.tecnicoResponsavel);\n      // Não muda o dropdown de Instrumento automaticamente aqui: trocar de\n      // instrumento reconstrói os campos de certificado (um por peça\n      // calibrável) e apagaria o arquivo que o operador acabou de anexar\n      // (input de arquivo não pode ser repovoado via JS). O instrumento já\n      // devia estar selecionado ANTES de anexar o certificado.\n\n      if (statusEl) statusEl.innerHTML = \'<div class="field-help">Dados detectados automaticamente a partir do certificado — revise antes de gerar.</div>\';\n      tplRelCal_writeLog(\'Dados do certificado detectados com sucesso.\', \'SUCESSO\');\n    }).catch(function() {\n      if (!deteccaoAindaAtual()) return;\n      if (statusEl) statusEl.innerHTML = \'<div class="field-help">Não foi possível detectar os dados automaticamente — preencha manualmente.</div>\';\n        tplRelCal_writeLog(\'Não foi possível detectar os dados do certificado automaticamente.\', \'AVISO\');\n    });\n  }\n\n  function tplRelCal_montarPayload_() {\n    return {\n      cnpj: document.getElementById(\'tplRelCal_cnpj\').value,\n      cliente: document.getElementById(\'tplRelCal_cliente\').value,\n      endereco: document.getElementById(\'tplRelCal_endereco\').value,\n      instrumento: document.getElementById(\'tplRelCal_instrumento\').value,\n      tagEquipamento: document.getElementById(\'tplRelCal_tag\').value,\n      marca: document.getElementById(\'tplRelCal_marca\').value,\n      modelo: document.getElementById(\'tplRelCal_modelo\').value,\n      localizacao: document.getElementById(\'tplRelCal_localizacao\').value,\n      dataCalibracao: document.getElementById(\'tplRelCal_dataCalibracao\').value,\n      tecnicoResponsavel: document.getElementById(\'tplRelCal_tecnicoResponsavel\').value,\n      localCalibracao: document.getElementById(\'tplRelCal_localLaboratorio\').checked ? \'LABORATORIO\' : \'CLIENTE\',\n      observacoesTecnico: document.getElementById(\'tplRelCal_observacoesTecnico\').value,\n      numeroDocumento: document.getElementById(\'tplRelCal_numeroDocumento\').value\n    };\n  }\n\n  function tplRelCal_gerarRelatorio() {\n    const btn = document.getElementById(\'tplRelCal_btnGerar\');\n    btn.disabled = true;\n    document.getElementById(\'tplRelCal_statusArea\').innerHTML = \'Lendo o(s) certificado(s) e gerando o relatório com IA — pode levar até 1 minuto...\';\n    tplRelCal_writeLog(\'Iniciando geração do Relatório de Calibração...\', \'SUCESSO\');\n\n    const novaJanela = window.open(\'\', \'_blank\');\n    if (novaJanela) {\n      novaJanela.document.write(\'<p style="font-family:Arial,sans-serif;padding:40px;color:#374151;">Gerando relatório de calibração, aguarde...</p>\');\n    }\n\n    let payloadCapturado_ = null;\n\n    Promise.all([\n      tplRelCal_coletarCertificados_(),\n      tplRelCal_coletarFotos_(\'tplRelCal_foto\', 6)\n    ]).then(function(resultados) {\n      const certificados = resultados[0];\n      if (!certificados.some(function(c) { return c.base64; })) {\n        throw new Error(\'Anexe ao menos um certificado de calibração (PDF ou imagem) antes de gerar o relatório.\');\n      }\n      const payload = tplRelCal_montarPayload_();\n      payload.certificados = certificados;\n      payload.fotos = resultados[1];\n      payloadCapturado_ = payload;\n      return tplRelCal_chamarApi(\'apiGerarDocumento\', payload);\n    }).then(function(res) {\n      btn.disabled = false;\n      RELCAL_ULTIMO_HTML = res.html;\n      tplRelCal_writeLog(\'Relatório de Calibração gerado.\', \'SUCESSO\');\n\n      // Congela cliente/TAG/instrumento deste relatório ANTES de limpar o\n      // formulário logo abaixo — "Salvar na pasta do cliente" passa a usar esses\n      // valores congelados, não mais o DOM ao vivo (ver\n      // tplRelCal_salvarDocumento), então o reset não quebra o Salvar.\n      RELCAL_ULTIMO_CLIENTE = payloadCapturado_ ? payloadCapturado_.cliente : \'\';\n      RELCAL_ULTIMO_TAG = payloadCapturado_ ? payloadCapturado_.tagEquipamento : \'\';\n      const selInst_ = document.getElementById(\'tplRelCal_instrumento\');\n      const chaveInst_ = payloadCapturado_ ? payloadCapturado_.instrumento : \'\';\n      const infoInst_ = (RELCAL_CFG_CLIENTE && RELCAL_CFG_CLIENTE.instrumentos) ? RELCAL_CFG_CLIENTE.instrumentos[chaveInst_] : null;\n      RELCAL_ULTIMO_INSTRUMENTO_LABEL = infoInst_ ? infoInst_.label : \'\';\n\n      if (novaJanela) {\n        novaJanela.document.open();\n        novaJanela.document.write(res.html);\n        novaJanela.document.close();\n      }\n      document.getElementById(\'tplRelCal_statusArea\').innerHTML =\n        \'<div class="alert-box success">Relatório de Calibração gerado e aberto em nova aba. \' +\n        \'<button type="button" class="btn btn-secondary" style="margin-left:10px;" onclick="tplRelCal_salvarDocumento()">Salvar na pasta do cliente</button></div>\';\n\n      // Achado real 2026-07-29: sem isso, quem gera vários relatórios em\n      // sequência encontrava o formulário ainda cheio com os dados do\n      // relatório ANTERIOR — e como a detecção automática só preenche\n      // campo vazio (nunca sobrescreve, ver tplRelCal_aoAnexarCertificado),\n      // os dados antigos ficavam silenciosamente, sem nenhum aviso, e\n      // vazavam pro próximo relatório (cliente, TAG, número do\n      // certificado, data, técnico...). Limpa tudo assim que o relatório\n      // atual já foi gerado, deixando a tela pronta pro próximo.\n      tplRelCal_prepararProximoRelatorio_();\n      if (res.avisos && res.avisos.length) {\n        const elAv = document.getElementById(\'tplRelCal_statusArea\');\n        if (elAv) { const dv = document.createElement(\'div\'); dv.className = \'alert-box error\'; dv.style.marginTop = \'8px\'; dv.textContent = res.avisos.join(\' \'); elAv.appendChild(dv); }\n        tplRelCal_writeLog(res.avisos.join(\' \'), \'ERRO\');\n      }\n      // O relatório é salvo sozinho na pasta do cliente assim que é gerado.\n      tplRelCal_salvarDocumento();\n    }).catch(function(err) {\n      btn.disabled = false;\n      if (novaJanela) novaJanela.close();\n      tplRelCal_writeLog(\'Não foi possível gerar o relatório: \' + ((err && err.message) ? err.message : err) + \'. Confira os dados da seção indicada e gere de novo.\', \'ERRO\');\n      tplRelCal_mostrarErro(\'tplRelCal_statusArea\', err);\n    });\n  }\n\n  function tplRelCal_prepararProximoRelatorio_() {\n    [\n      \'tplRelCal_cnpj\', \'tplRelCal_cliente\', \'tplRelCal_endereco\', \'tplRelCal_tag\', \'tplRelCal_marca\',\n      \'tplRelCal_modelo\', \'tplRelCal_localizacao\', \'tplRelCal_dataCalibracao\', \'tplRelCal_tecnicoResponsavel\',\n      \'tplRelCal_numeroDocumento\', \'tplRelCal_observacoesTecnico\'\n    ].forEach(function(id) {\n      const el = document.getElementById(id);\n      if (el) el.value = \'\';\n    });\n\n    const localLab = document.getElementById(\'tplRelCal_localLaboratorio\');\n    if (localLab) localLab.checked = true;\n\n    // <input type="file"> não pode ser esvaziado só com .value = \'\' de\n    // forma confiável entre navegadores — reconstrói os slots (mesmo\n    // instrumento ainda selecionado) pra garantir que nenhum arquivo do\n    // relatório anterior continue anexado.\n    tplRelCal_renderCertificadoSlots_(RELCAL_ITENS_CALIBRAVEIS_ATUAL);\n    tplRelCal_renderFotosSlots_(\'tplRelCal_fotosGrid\', \'tplRelCal_foto\', 6);\n\n    const statusDet = document.getElementById(\'tplRelCal_statusDeteccao\');\n    if (statusDet) statusDet.innerHTML = \'\';\n    tplRelCal_writeLog(\'Tela limpa automaticamente — pronta para o próximo relatório.\', \'SUCESSO\');\n  }\n\n  var RELCAL_ULTIMO_SALVO_HTML_ = null;\n  function tplRelCal_salvarDocumento() {\n    if (!RELCAL_ULTIMO_HTML) return;\n    if (RELCAL_ULTIMO_SALVO_HTML_ === RELCAL_ULTIMO_HTML) { tplRelCal_writeLog(\'Este relatório já está salvo na pasta do cliente.\', \'SUCESSO\'); return; }\n    RELCAL_ULTIMO_SALVO_HTML_ = RELCAL_ULTIMO_HTML;\n    tplRelCal_writeLog(\'Salvando documento na pasta do cliente...\', \'SUCESSO\');\n\n    tplRelCal_chamarApi(\'apiSalvarDocumento\', {\n      html: RELCAL_ULTIMO_HTML,\n      cnpj: (document.getElementById(\'tplRelCal_cnpj\') || {}).value || \'\',\n      cliente: RELCAL_ULTIMO_CLIENTE,\n      instrumentoLabel: RELCAL_ULTIMO_INSTRUMENTO_LABEL,\n      tag: RELCAL_ULTIMO_TAG\n    }).then(function(res) {\n      const el = document.getElementById(\'tplRelCal_statusArea\');\n      if (el) {\n        el.innerHTML += \'<div class="alert-box success" style="margin-top:8px;">Salvo na pasta do cliente: <a href="\' + res.url + \'" target="_blank">\' + res.fileName + \'</a></div>\';\n      }\n      tplRelCal_writeLog(\'Documento salvo na pasta do cliente: \' + res.fileName, \'SUCESSO\');\n      RELCAL_VINC_ULTIMO_NOME_ = res.fileName;\n      RELCAL_VINC_ULTIMO_URL_ = res.url;\n      tplRelCal_renderPainelVincular_();\n    }).catch(function(err) {\n      RELCAL_ULTIMO_SALVO_HTML_ = null;\n      tplRelCal_writeLog(\'Não foi possível salvar na pasta do cliente: \' + ((err && err.message) ? err.message : err) + \'. Tente de novo em instantes.\', \'ERRO\');\n      tplRelCal_mostrarErro(\'tplRelCal_statusArea\', err);\n    });\n  }\n\n  function tplRelCal_renderPainelVincular_() {\n    const el = document.getElementById(\'tplRelCal_statusArea\');\n    if (!el) return;\n    el.innerHTML += \'<div class="panel" style="margin-top:10px;">\' +\n      \'<h2 style="margin:0 0 10px;font-size:13px;">Vincular ao Cadastro (pra aparecer no Invent\\u00e1rio de Equipamentos)</h2>\' +\n      \'<div class="form-row">\' +\n        \'<div class="form-group"><label>Cliente</label><select id="tplRelCal_vincCliente" class="form-control" onchange="tplRelCal_vincAoMudarCliente_()"><option value="">Selecione...</option></select></div>\' +\n        \'<div class="form-group"><label>Unidade</label><select id="tplRelCal_vincUnidade" class="form-control" onchange="tplRelCal_vincAoMudarUnidade_()"><option value="">Selecione o cliente primeiro</option></select></div>\' +\n        \'<div class="form-group"><label>Equipamento</label><select id="tplRelCal_vincEquipamento" class="form-control"><option value="">Selecione a unidade primeiro</option></select></div>\' +\n        \'<div class="form-group"><label>Data de Vencimento (opcional)</label><input id="tplRelCal_vincVencimento" type="date" class="form-control"></div>\' +\n      \'</div>\' +\n      \'<button type="button" class="btn btn-primary" onclick="tplRelCal_vincular_()">Vincular</button>\' +\n      \'<div id="tplRelCal_vincStatus" style="margin-top:8px;"></div>\' +\n    \'</div>\';\n    tplRelCal_vincCarregarClientes_();\n  }\n\n  function tplRelCal_vincCarregarClientes_() {\n    google.script.run.withSuccessHandler(function (res) {\n      const sel = document.getElementById(\'tplRelCal_vincCliente\');\n      if (!sel || !res || !res.success) return;\n      sel.innerHTML = \'<option value="">Selecione...</option>\' + (res.items || []).map(function (c) {\n        return \'<option value="\' + c.ID + \'">\' + c.NOME + \'</option>\';\n      }).join(\'\');\n    }).withFailureHandler(function () {}).equipamentosListarClientesAtivos(SESSION);\n  }\n\n  function tplRelCal_vincAoMudarCliente_() {\n    const clienteId = document.getElementById(\'tplRelCal_vincCliente\').value;\n    const selUni = document.getElementById(\'tplRelCal_vincUnidade\');\n    const selEq = document.getElementById(\'tplRelCal_vincEquipamento\');\n    selEq.innerHTML = \'<option value="">Selecione a unidade primeiro</option>\';\n    if (!clienteId) { selUni.innerHTML = \'<option value="">Selecione o cliente primeiro</option>\'; return; }\n    selUni.innerHTML = \'<option value="">Carregando...</option>\';\n    google.script.run.withSuccessHandler(function (res) {\n      const itens = (res && res.items) || [];\n      selUni.innerHTML = \'<option value="">Selecione...</option>\' + itens.map(function (u) {\n        return \'<option value="\' + u.ID + \'">\' + u.NOME_UNIDADE + \'</option>\';\n      }).join(\'\');\n    }).withFailureHandler(function () { selUni.innerHTML = \'<option value="">Falha ao carregar</option>\'; }).equipamentosListarUnidadesAtivasPorCliente(SESSION, clienteId);\n  }\n\n  function tplRelCal_vincAoMudarUnidade_() {\n    const unidadeId = document.getElementById(\'tplRelCal_vincUnidade\').value;\n    const selEq = document.getElementById(\'tplRelCal_vincEquipamento\');\n    if (!unidadeId) { selEq.innerHTML = \'<option value="">Selecione a unidade primeiro</option>\'; return; }\n    selEq.innerHTML = \'<option value="">Carregando...</option>\';\n    google.script.run.withSuccessHandler(function (res) {\n      const itens = (res && res.items) || [];\n      selEq.innerHTML = \'<option value="">(opcional)</option>\' + itens.map(function (e) {\n        return \'<option value="\' + e.ID + \'">\' + e.NOME_EQUIPAMENTO + \'</option>\';\n      }).join(\'\');\n    }).withFailureHandler(function () { selEq.innerHTML = \'<option value="">Falha ao carregar</option>\'; }).documentosListarEquipamentosAtivosPorUnidade(SESSION, unidadeId);\n  }\n\n  function tplRelCal_vincular_() {\n    const clienteId = document.getElementById(\'tplRelCal_vincCliente\').value;\n    const unidadeId = document.getElementById(\'tplRelCal_vincUnidade\').value;\n    const equipamentoId = document.getElementById(\'tplRelCal_vincEquipamento\').value;\n    const vencimento = document.getElementById(\'tplRelCal_vincVencimento\').value;\n    const statusEl = document.getElementById(\'tplRelCal_vincStatus\');\n    if (!clienteId || !unidadeId) { if (statusEl) statusEl.innerHTML = \'<div class="alert-box error">Escolha ao menos Cliente e Unidade.</div>\'; return; }\n\n    google.script.run.withSuccessHandler(function (res) {\n      if (!res || !res.success) { if (statusEl) statusEl.innerHTML = \'<div class="alert-box error">\' + ((res && res.message) || \'Falha ao vincular.\') + \'</div>\'; return; }\n      if (statusEl) statusEl.innerHTML = \'<div class="alert-box success">Vinculado! J\\u00e1 aparece no Invent\\u00e1rio de Equipamentos.</div>\';\n    }).withFailureHandler(function (err) {\n      if (statusEl) statusEl.innerHTML = \'<div class="alert-box error">Erro: \' + ((err && err.message) || err) + \'</div>\';\n    }).documentosRegistrarExistente(SESSION, {\n      CLIENTE_ID: clienteId,\n      UNIDADE_ID: unidadeId,\n      EQUIPAMENTO_ID: equipamentoId,\n      TIPO_DOCUMENTO: \'2. Certificados de Calibra\\u00e7\\u00e3o\',\n      NOME_ARQUIVO: RELCAL_VINC_ULTIMO_NOME_,\n      LINK_ARQUIVO: RELCAL_VINC_ULTIMO_URL_,\n      DATA_VENCIMENTO: vencimento\n    });\n  }\n\n  function tplRelCal_buscarDocumentosSalvos() {\n    const termo = document.getElementById(\'tplRelCal_buscaDocumentos\').value;\n    const lista = document.getElementById(\'tplRelCal_listaDocumentosSalvos\');\n    lista.innerHTML = \'Buscando...\';\n    tplRelCal_chamarApi(\'apiListarDocumentosSalvos\', { termoBusca: termo }).then(function(res) {\n      const docs = res.documentos || [];\n      if (!docs.length) { lista.innerHTML = \'<div class="field-help">Nenhum documento encontrado.</div>\'; return; }\n      lista.innerHTML = \'<ul class="lista-documentos-salvos">\' + docs.map(function(d) {\n        return \'<li><a href="\' + d.url + \'" target="_blank">\' + d.fileName + \'</a> — \' + d.cliente + \'</li>\';\n      }).join(\'\') + \'</ul>\';\n    }).catch(function(err) {\n      tplRelCal_mostrarErro(\'tplRelCal_listaDocumentosSalvos\', err);\n    });\n  }\n\n  function tplRelCal_inicializar() {\n    tplRelCal_setStatusBadge(\'carregando...\', \'is-neutral\');\n    tplRelCal_renderFotosSlots_(\'tplRelCal_fotosGrid\', \'tplRelCal_foto\', 6);\n    \n\n    tplRelCal_chamarApi(\'apiPing\', {}).then(function(cfg) {\n      RELCAL_CFG_CLIENTE = cfg;\n      tplRelCal_setStatusBadge(\'pronto\', \'\');\n      \n\n      const sel = document.getElementById(\'tplRelCal_instrumento\');\n      sel.innerHTML = \'\';\n      Object.keys(cfg.instrumentos).forEach(function(chave) {\n        const it = cfg.instrumentos[chave];\n        const opt = document.createElement(\'option\');\n        opt.value = chave;\n        opt.textContent = it.label;\n        sel.appendChild(opt);\n      });\n      tplRelCal_aoTrocarInstrumento();\n    }).catch(function(err) {\n      tplRelCal_setStatusBadge(\'erro\', \'is-danger\');\n      tplRelCal_writeLog(\'Não foi possível carregar a configuração: \' + ((err && err.message) ? err.message : err) + \'. Recarregue a página (F5).\', \'ERRO\');\n      tplRelCal_mostrarErro(\'tplRelCal_statusArea\', err);\n    });\n  }\n\n  function tplRelCal_renderReal_() {\n    const container = document.getElementById(\'tplRelCalContainer\');\n    if (!container) return;\n    container.innerHTML = TPL_RELCAL_HTML_;\n    tplRelCal_inicializar();\n  }\n\n  const TPL_RELCAL_HTML_ = "<div class=\\"wrap\\" id=\\"tplRelCal_viewModulo\\">\\n  <header class=\\"header-card\\">\\n    <div class=\\"brand\\">\\n      <div class=\\"title-area\\">\\n        <h1>Relatório de Calibração</h1>\\n        <p>Instrumentos simples calibrados no laboratório da Metrolabs — certificado + fotos, relatório explicado de forma didática.</p>\\n      </div>\\n    </div>\\n    <div style=\\"display:flex; align-items:center; gap:10px;\\">\\n      <button type=\\"button\\" class=\\"btn btn-secondary\\" onclick=\\"tplRelCal_abrirManual_()\\">Manual do Operador</button>\\n      <div id=\\"tplRelCal_statusBadge\\" class=\\"status-badge is-neutral\\">pronto</div>\\n    </div>\\n  </header>\\n\\n  <div class=\\"panel\\">\\n    <h2>1. Cliente</h2>\\n    <div class=\\"form-row\\">\\n      <div class=\\"form-group\\">\\n        <label for=\\"tplRelCal_cnpj\\">CNPJ</label>\\n        <input id=\\"tplRelCal_cnpj\\" class=\\"form-control\\" placeholder=\\"00.000.000/0000-00\\">\\n      </div>\\n      <div class=\\"form-group\\" style=\\"display:flex; align-items:flex-end;\\">\\n        <button type=\\"button\\" class=\\"btn btn-secondary\\" onclick=\\"tplRelCal_buscarCnpj()\\">Buscar CNPJ</button>\\n      </div>\\n    </div>\\n    <div class=\\"form-row\\">\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_cliente\\">Cliente / Razão Social</label><input id=\\"tplRelCal_cliente\\" class=\\"form-control\\"></div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_endereco\\">Endereço</label><input id=\\"tplRelCal_endereco\\" class=\\"form-control\\"></div>\\n    </div>\\n  </div>\\n\\n  <div class=\\"panel\\">\\n    <h2>2. Instrumento</h2>\\n    <div class=\\"form-row\\">\\n      <div class=\\"form-group\\">\\n        <label for=\\"tplRelCal_instrumento\\">Instrumento</label>\\n        <select id=\\"tplRelCal_instrumento\\" class=\\"form-control\\" onchange=\\"tplRelCal_aoTrocarInstrumento()\\"></select>\\n      </div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_tag\\">TAG / Identificação</label><input id=\\"tplRelCal_tag\\" class=\\"form-control\\"></div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_marca\\">Marca</label><input id=\\"tplRelCal_marca\\" class=\\"form-control\\"></div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_modelo\\">Modelo</label><input id=\\"tplRelCal_modelo\\" class=\\"form-control\\"></div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_localizacao\\">Localização habitual do instrumento</label><input id=\\"tplRelCal_localizacao\\" class=\\"form-control\\"></div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_dataCalibracao\\">Data da calibração</label><input id=\\"tplRelCal_dataCalibracao\\" class=\\"form-control\\" placeholder=\\"dd/MM/aaaa\\"></div>\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_tecnicoResponsavel\\">Técnico responsável</label><input id=\\"tplRelCal_tecnicoResponsavel\\" class=\\"form-control\\"></div>\\n    </div>\\n\\n    <div class=\\"section-divider\\">Local da calibração</div>\\n    <div class=\\"check-item\\" style=\\"max-width:420px;\\">\\n      <input type=\\"checkbox\\" id=\\"tplRelCal_localLaboratorio\\" checked>\\n      <label for=\\"tplRelCal_localLaboratorio\\" style=\\"margin:0;\\">Realizado no laboratório da Metrolabs</label>\\n    </div>\\n    <div class=\\"field-help\\">Desmarque só nos casos raros em que a calibração foi feita nas instalações do cliente — isso muda a redação do relatório.</div>\\n\\n    <div class=\\"form-group\\">\\n      <label for=\\"tplRelCal_observacoesTecnico\\">Observações do técnico sobre esta calibração (opcional)</label>\\n      <textarea id=\\"tplRelCal_observacoesTecnico\\" class=\\"form-control\\" style=\\"min-height:70px;\\" placeholder=\\"Ex.: condição do instrumento antes da calibração, particularidades do atendimento...\\"></textarea>\\n    </div>\\n  </div>\\n\\n  <div class=\\"panel\\">\\n    <h2>3. Certificado e Fotos</h2>\\n    <div class=\\"field-help\\">A IA lê o certificado anexado e escreve o relatório inteiro, explicando cada resultado de forma didática — sem arredondar nem reescrever nenhum número.</div>\\n\\n    <div class=\\"section-divider\\">Certificado(s) de calibração (obrigatório ao menos 1 — PDF ou imagem)</div>\\n    <div class=\\"field-help\\" id=\\"tplRelCal_helpMultiCert\\" style=\\"margin-bottom:8px;\\">Instrumentos com mais de uma peça calibrada (ex.: centrífuga) mostram um campo de certificado por peça — anexe cada um separadamente, nunca junte vários certificados num arquivo só.</div>\\n    <div class=\\"check-item\\" style=\\"max-width:480px; margin-bottom:10px;\\">\\n      <input type=\\"checkbox\\" id=\\"tplRelCal_detectarAuto\\" checked>\\n      <label for=\\"tplRelCal_detectarAuto\\" style=\\"margin:0;\\">Detectar automaticamente os dados do certificado (cliente, TAG, marca, modelo, número, data...)</label>\\n    </div>\\n    <div class=\\"check-grid-multiarquivo check-grid\\" id=\\"tplRelCal_certificadosGrid\\"></div>\\n    <div id=\\"tplRelCal_statusDeteccao\\"></div>\\n\\n    <div class=\\"section-divider\\">Registros fotográficos (até 6, opcional)</div>\\n    <div class=\\"field-help\\">A IA analisa cada foto automaticamente e gera uma legenda descritiva — não precisa escrever nada, a legenda de texto é só um complemento opcional.</div>\\n    <div class=\\"check-grid-multiarquivo check-grid\\" id=\\"tplRelCal_fotosGrid\\"></div>\\n\\n    <div class=\\"section-divider\\">Número do documento</div>\\n    <div class=\\"form-row\\">\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_numeroDocumento\\">Número do documento (opcional — não é uma data)</label><input id=\\"tplRelCal_numeroDocumento\\" class=\\"form-control\\" placeholder=\\"ex.: 202601763\\"></div>\\n    </div>\\n\\n    <div class=\\"btn-container\\">\\n      <button type=\\"button\\" class=\\"btn btn-primary\\" id=\\"tplRelCal_btnGerar\\" onclick=\\"tplRelCal_gerarRelatorio()\\">Gerar Relatório de Calibração</button>\\n    </div>\\n    <div id=\\"tplRelCal_statusArea\\"></div>\\n  </div>\\n\\n  <div class=\\"panel\\">\\n    <h2>Documentos já gerados</h2>\\n    <div class=\\"field-help\\">Busque relatórios já gerados sem precisar gerar de novo.</div>\\n    <div class=\\"form-row\\">\\n      <div class=\\"form-group\\"><label for=\\"tplRelCal_buscaDocumentos\\">Buscar por cliente, TAG ou nome do arquivo</label><input id=\\"tplRelCal_buscaDocumentos\\" class=\\"form-control\\" placeholder=\\"Ex.: Hospital Exemplo, CORA-0587...\\"></div>\\n      <div class=\\"form-group\\" style=\\"display:flex; align-items:flex-end;\\"><button type=\\"button\\" class=\\"btn btn-secondary\\" onclick=\\"tplRelCal_buscarDocumentosSalvos()\\">Buscar</button></div>\\n    </div>\\n    <div id=\\"tplRelCal_listaDocumentosSalvos\\"></div>\\n  </div>\\n\\n\\n  <div class=\\"panel\\">\\n    <h2>Histórico da operação</h2>\\n    <div class=\\"terminal-wrap\\">\\n      <div class=\\"terminal-header\\">Histórico da operação</div>\\n      <div id=\\"tplRelCal_terminalLog\\" class=\\"terminal\\"></div>\\n    </div>\\n  </div></div>\\n\\n<div id=\\"tplRelCal_viewManual\\" style=\\"display:none\\">\\n<div class=\\"wrap manual-wrap\\">\\n\\n  <header class=\\"header-card\\" style=\\"position:static; margin-bottom:24px;\\">\\n    <div class=\\"brand\\">\\n      <div class=\\"title-area\\">\\n        <h1 style=\\"margin-bottom:4px;\\">Manual do Operador</h1>\\n        <p style=\\"margin:0;\\">Relatório de Calibração — instrumentos simples calibrados no laboratório da Metrolabs</p>\\n      </div>\\n    </div>\\n    <button type=\\"button\\" class=\\"btn btn-secondary\\" onclick=\\"tplRelCal_voltarDoManual_()\\">← Voltar ao sistema</button>\\n  </header>\\n\\n  <div class=\\"toc\\" id=\\"tplRelCal_topoManual\\">\\n    <h2>Índice</h2>\\n    <ol>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms1\'); return false;\\">Como usar este manual</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms2\'); return false;\\">O que este sistema faz</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms3\'); return false;\\">Os 9 tipos de instrumento</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms4\'); return false;\\">Mapa da tela</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms5\'); return false;\\">Seção 1 — Cliente</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms6\'); return false;\\">Seção 2 — Instrumento</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms7\'); return false;\\">Seção 3 — Certificado e Fotos</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms8\'); return false;\\">Gerar Relatório de Calibração</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms9\'); return false;\\">Documentos já gerados</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms10\'); return false;\\">Passo a passo do zero</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms11\'); return false;\\">Erros comuns</a></li>\\n      <li><a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms12\'); return false;\\">Glossário</a></li>\\n    </ol>\\n  </div>\\n\\n  <h2 id=\\"tplRelCal_ms1\\">1. Como usar este manual</h2>\\n  <p>Este manual foi escrito para quem <strong>nunca usou o sistema e não precisa entender de engenharia ou metrologia</strong> para operá-lo. Cada campo da tela está explicado em quatro partes:</p>\\n  <ul>\\n    <li><strong>O que é</strong> — o nome em português simples do que você está vendo.</li>\\n    <li><strong>Para que serve</strong> — por que esse campo existe.</li>\\n    <li><strong>O que fazer</strong> — como preencher, na prática.</li>\\n    <li><strong>O que acontece</strong> — o resultado de preencher certo, errado, ou deixar em branco.</li>\\n  </ul>\\n  <p>Leia este manual <strong>na ordem</strong>. Se aparecer uma palavra técnica que você não entende, vá direto ao <a href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_ms12\'); return false;\\">Glossário</a>.</p>\\n\\n  <h2 id=\\"tplRelCal_ms2\\">2. O que este sistema faz, em uma frase</h2>\\n  <p>Você anexa o <strong>certificado de calibração real</strong> de um instrumento simples (termômetro, balança, esfigmomanômetro, etc.), o sistema <strong>lê o certificado automaticamente</strong> e escreve um relatório inteiro, com Inteligência Artificial, explicando de forma didática cada resultado — sem arredondar nem reescrever nenhum número.</p>\\n  <p>Este é um módulo <strong>separado</strong> da Declaração de Execução de Serviço e do Relatório de QI/QO/QD: aqui <strong>não existe etapa de instalação ou operação</strong> — são instrumentos de bancada ou de bolso, calibrados principalmente <strong>no laboratório da própria Metrolabs</strong> (diferente do resto do Portal, que assume atendimento em campo por padrão).</p>\\n\\n  <h2 id=\\"tplRelCal_ms3\\">3. Os 9 tipos de instrumento</h2>\\n  <p>Você escolhe <strong>um</strong> instrumento na tela (campo \\"Instrumento\\", seção 2).</p>\\n  <table>\\n    <tr><th>Instrumento</th><th>Peças calibráveis (certificados separados)</th></tr>\\n    <tr><td>Termo-higrômetro</td><td>1 certificado só</td></tr>\\n    <tr><td>Termômetro</td><td>1 certificado só</td></tr>\\n    <tr><td>Esfigmomanômetro</td><td>1 certificado só</td></tr>\\n    <tr><td>Balança</td><td>1 certificado só</td></tr>\\n    <tr><td>Centrífuga (sem refrigeração)</td><td>Temporizador/Cronômetro do ciclo + Indicador de Rotação (RPM) — 2 certificados separados</td></tr>\\n    <tr><td>Centrífuga Refrigerada</td><td>Temporizador/Cronômetro do ciclo + Indicador de Rotação (RPM) + Sensor de Temperatura — 3 certificados separados</td></tr>\\n    <tr><td>Incubadora de Testes Biológicos</td><td>1 certificado só</td></tr>\\n    <tr><td>Estufa de Incubação (bancada de laboratório)</td><td>1 certificado só</td></tr>\\n    <tr><td>Banho-maria (bancada de laboratório)</td><td>1 certificado só</td></tr>\\n  </table>\\n  <p><strong>Por que a Centrífuga tem mais de um certificado?</strong> Porque, na prática, o temporizador, o indicador de rotação e (na versão refrigerada) o sensor de temperatura são calibrados como peças separadas, cada uma com seu próprio certificado emitido pelo laboratório de calibração. O sistema mostra <strong>um campo de upload para cada peça</strong> — nunca junte vários certificados num arquivo só, isso pode confundir a leitura automática de qual dado pertence a qual peça.</p>\\n\\n  <h2 id=\\"tplRelCal_ms4\\">4. Mapa da tela — visão geral</h2>\\n  <ol>\\n    <li><strong>Cliente</strong> — quem é o dono do instrumento.</li>\\n    <li><strong>Instrumento</strong> — qual instrumento foi calibrado, com quais dados, e onde a calibração foi feita.</li>\\n    <li><strong>Certificado e Fotos</strong> — os certificados de calibração (obrigatório ao menos um), fotos opcionais, e o botão que gera o relatório.</li>\\n    <li><strong>Documentos já gerados</strong> — busca de relatórios antigos.</li>\\n  </ol>\\n\\n  <h2 id=\\"tplRelCal_ms5\\">5. Seção 1 — Cliente</h2>\\n  <table>\\n    <tr><th>Campo</th><th>O que é</th><th>Para que serve</th><th>O que fazer</th></tr>\\n    <tr><td><code class=\\"campo\\">CNPJ</code></td><td>Número de identificação da empresa cliente</td><td>Preenche automaticamente nome e endereço</td><td>Digite o CNPJ e clique em \\"Buscar CNPJ\\"</td></tr>\\n    <tr><td>Buscar CNPJ (botão)</td><td>Dispara a busca automática</td><td>Evita digitar manualmente</td><td>Clique depois de digitar o CNPJ</td></tr>\\n    <tr><td>Cliente / Razão Social</td><td>Nome oficial da empresa</td><td>Aparece na capa do documento</td><td>Confira depois da busca; corrija manualmente se necessário</td></tr>\\n    <tr><td>Endereço</td><td>Endereço da empresa</td><td>Aparece na capa do documento</td><td>Mesma lógica</td></tr>\\n  </table>\\n\\n  <h2 id=\\"tplRelCal_ms6\\">6. Seção 2 — Instrumento</h2>\\n  <table>\\n    <tr><th>Campo</th><th>O que é</th><th>Para que serve</th><th>O que fazer</th></tr>\\n    <tr><td>Instrumento (dropdown)</td><td>O tipo de instrumento calibrado (seção 3 deste manual)</td><td>Define quantos slots de certificado aparecem na seção 3 da tela</td><td>Escolha <strong>antes</strong> de anexar qualquer certificado — trocar depois reconstrói os campos e você perderia o arquivo já anexado</td></tr>\\n    <tr><td>TAG / Identificação</td><td>Código interno do instrumento</td><td>Identifica qual instrumento específico foi calibrado</td><td>Copie do instrumento físico ou peça ao cliente</td></tr>\\n    <tr><td>Marca / Modelo</td><td>Fabricante e modelo</td><td>Identificação no documento</td><td>Digite conforme a placa</td></tr>\\n    <tr><td>Localização habitual do instrumento</td><td>Onde o instrumento fica normalmente</td><td>Rastreabilidade</td><td>Digite o local</td></tr>\\n    <tr><td>Data da calibração</td><td>Data em que a calibração foi realizada</td><td>Aparece no documento</td><td><code class=\\"campo\\">dd/MM/aaaa</code></td></tr>\\n    <tr><td>Técnico responsável</td><td>Quem realizou a calibração</td><td>Responsável no documento</td><td>Nome completo</td></tr>\\n  </table>\\n  <h3>Local da calibração</h3>\\n  <table>\\n    <tr><th>Campo</th><th>O que é</th><th>O que fazer</th></tr>\\n    <tr><td>Realizado no laboratório da Metrolabs (já vem marcado)</td><td>Diz se a calibração foi no laboratório ou no cliente</td><td><strong>Diferente dos outros módulos do Portal</strong>, aqui a caixa já vem <strong>marcada</strong> por padrão. Desmarque só nos casos raros em que foi feito nas instalações do cliente</td></tr>\\n  </table>\\n  <h3>Observações do técnico (opcional)</h3>\\n  <table>\\n    <tr><th>Campo</th><th>O que é</th><th>Para que serve</th><th>O que fazer</th></tr>\\n    <tr><td>Observações do técnico sobre esta calibração</td><td>Texto livre</td><td>Enriquece o relatório com contexto real</td><td>Escreva livremente — a IA usa como contexto adicional, nunca como substituto dos dados do certificado</td></tr>\\n  </table>\\n\\n  <h2 id=\\"tplRelCal_ms7\\">7. Seção 3 — Certificado e Fotos</h2>\\n  <table>\\n    <tr><th>Campo</th><th>O que é</th><th>Para que serve</th><th>O que fazer</th></tr>\\n    <tr><td>Detectar automaticamente os dados do certificado (já vem marcada)</td><td>Liga a leitura automática do certificado pela IA</td><td>Assim que você anexa o certificado, o sistema lê e preenche sozinho cliente, TAG, marca, modelo, número, data e técnico</td><td>Deixe marcado no uso normal. Desmarque só se quiser preencher tudo manualmente</td></tr>\\n    <tr><td>Certificado(s) de calibração (1 slot por peça, obrigatório ao menos 1)</td><td>O certificado real emitido pelo laboratório</td><td>A IA lê o certificado e escreve o relatório com base nos dados reais</td><td>Anexe o certificado de cada peça. Nunca junte vários num arquivo só</td></tr>\\n    <tr><td>Registros fotográficos (até 6, opcional)</td><td>Fotos do instrumento/calibração</td><td>A IA analisa cada foto automaticamente e gera legenda sozinha</td><td>Anexe as fotos relevantes</td></tr>\\n    <tr><td>Número do documento (opcional)</td><td>Código de referência interno</td><td>Numeração/controle interno</td><td>Preencha só se tiver um código</td></tr>\\n  </table>\\n  <div class=\\"callout\\"><strong>O que acontece quando você anexa um certificado com \\"Detectar automaticamente\\" marcado?</strong> Aparece uma mensagem \\"Detectando dados do certificado automaticamente...\\" e, em poucos segundos, os campos da seção 2 são preenchidos sozinhos (só os que estavam vazios). Se a detecção falhar, aparece um aviso pedindo para preencher manualmente.</div><div class=\\"callout\\"><strong>E entre um relatório e outro?</strong> Assim que um relatório é gerado com sucesso, TODOS os campos da tela (cliente, TAG, marca, modelo, número, data, técnico, certificados e fotos anexados) são limpos automaticamente — a tela já fica pronta pro próximo relatório, sem nenhum dado do relatório anterior. Isso é proposital: evita que o operador, ao anexar o próximo certificado, acabe misturando dados de dois relatórios diferentes.</div>\\n\\n  <h2 id=\\"tplRelCal_ms8\\">8. Gerar Relatório de Calibração</h2>\\n  <p>Diferente da Declaração de Execução e do Relatório de QI/QO/QD, este módulo <strong>não tem uma etapa separada de rascunho/revisão</strong> — um único clique já vai direto para o documento final.</p>\\n  <ol>\\n    <li>Clique em <strong>\\"Gerar Relatório de Calibração\\"</strong>.</li>\\n    <li>Uma nova aba abre imediatamente, mostrando \\"Gerando relatório de calibração, aguarde...\\".</li>\\n    <li>O sistema lê o(s) certificado(s) e as fotos, e pede à IA para escrever o relatório inteiro — pode levar até 1 minuto.</li>\\n    <li>A aba é preenchida com o documento final completo.</li>\\n    <li>O relatório é <strong>salvo sozinho</strong> na pasta do cliente. Espere a mensagem verde \\"Salvo na pasta do cliente\\". Logo abaixo aparece o quadro \\"Vincular ao Cadastro\\": escolha cliente, unidade e equipamento e toque em \\"Vincular\\" para o documento aparecer no Inventário de equipamentos.</li>\\n      <li>A tela é limpa automaticamente, pronta pro próximo relatório — não precisa apagar nada manualmente antes de anexar o próximo certificado.</li>\\n  </ol>\\n  <div class=\\"callout\\"><strong>O que acontece se eu não anexar nenhum certificado?</strong> O sistema recusa gerar o relatório e avisa: \\"Anexe ao menos um certificado de calibração (PDF ou imagem) antes de gerar o relatório.\\" Sem certificado real, não há relatório.</div>\\n\\n  <h2 id=\\"tplRelCal_ms9\\">9. Documentos já gerados</h2>\\n  <p>Busque relatórios de calibração já salvos, por cliente, TAG ou nome do arquivo — sem precisar gerar de novo.</p>\\n\\n  <h2 id=\\"tplRelCal_ms10\\">10. Passo a passo — gerando um relatório do zero</h2>\\n  <ol>\\n    <li>Abra o módulo. Espere o selo de status virar \\"pronto\\".</li>\\n    <li><strong>Seção 1:</strong> CNPJ, buscar, conferir cliente/endereço.</li>\\n    <li><strong>Seção 2:</strong> escolha o instrumento certo <strong>antes</strong> de qualquer upload.</li>\\n    <li><strong>Seção 3:</strong> com \\"Detectar automaticamente\\" marcado, anexe o(s) certificado(s) — um por peça calibrável. Confira os campos preenchidos automaticamente. Anexe fotos se quiser.</li>\\n    <li>Clique em <strong>\\"Gerar Relatório de Calibração\\"</strong> e aguarde.</li>\\n    <li>Espere a mensagem \\"Salvo na pasta do cliente\\" e, se quiser, vincule o documento ao equipamento do cadastro.</li>\\n  </ol>\\n\\n  <h2 id=\\"tplRelCal_ms11\\">11. Erros comuns e o que fazer</h2>\\n  <table>\\n    <tr><th>O que aconteceu</th><th>Motivo mais provável</th><th>O que fazer</th></tr>\\n    <tr><td>\\"Anexe ao menos um certificado...\\" ao clicar em gerar</td><td>Nenhum certificado foi anexado, ou o upload falhou</td><td>Confira se o arquivo foi realmente selecionado</td></tr>\\n    <tr><td>A detecção automática não preencheu nada</td><td>Certificado ilegível, ou formato muito diferente do esperado</td><td>Preencha os campos manualmente — o relatório funciona do mesmo jeito</td></tr>\\n    <tr><td>Troquei o instrumento e o certificado que eu tinha anexado sumiu</td><td>Comportamento esperado — trocar de instrumento reconstrói os slots</td><td>Escolha o instrumento certo antes de anexar qualquer certificado</td></tr>\\n    <tr><td>Os dados detectados automaticamente vieram errados</td><td>O certificado real tinha esse dado diferente, ou a leitura confundiu algum campo</td><td>Revise e corrija manualmente antes de gerar</td></tr>\\n    <tr><td>Um campo já veio preenchido com um dado que não bate com o certificado atual</td><td>Você editou o campo manualmente ANTES de anexar o certificado desta peça (a detecção nunca sobrescreve o que já foi digitado, só preenche o que está vazio — mesmo dentro de um único relatório, ex.: 2ª peça de uma centrífuga)</td><td>Apague o campo e deixe a detecção preencher de novo, ou corrija manualmente</td></tr>\\n  </table>\\n\\n  <h2 id=\\"tplRelCal_ms12\\">12. Glossário</h2>\\n  <table>\\n    <tr><th>Termo</th><th>Explicação simples</th></tr>\\n    <tr><td>Instrumento</td><td>O tipo de equipamento de medição calibrado</td></tr>\\n    <tr><td>Certificado de calibração</td><td>Documento oficial emitido pelo laboratório, com os dados reais da calibração</td></tr>\\n    <tr><td>Peça calibrável</td><td>Parte específica de um instrumento composto que recebe seu próprio certificado</td></tr>\\n    <tr><td>Detecção automática</td><td>Recurso que lê o certificado via IA e preenche os campos sozinho</td></tr>\\n    <tr><td>Rastreabilidade metrológica</td><td>Garantia documentada de que a calibração está ligada a um padrão nacional/internacional reconhecido</td></tr>\\n  </table>\\n\\n  <p style=\\"margin-top:40px; color:var(--muted); font-size:12.5px;\\"><em>Este manual descreve o módulo Relatório de Calibração como está na tela em 17/10/2026. A ajuda rápida desta tela fica no botão \\\"Como usar esta tela\\\", no cabeçalho (no celular, na barra do topo). Se a IA não responder, o relatório sai com texto padrão (instrumento, normas, como ler o certificado anexado e conclusão sem veredito) e a tela avisa. Os perfis Comercial e Financeiro só consultam.</em></p>\\n\\n  <div class=\\"btn-container\\" style=\\"margin-top:20px;\\">\\n    <button type=\\"button\\" class=\\"btn btn-primary\\" onclick=\\"tplRelCal_voltarDoManual_()\\">← Voltar ao sistema</button>\\n  </div>\\n</div>\\n\\n<a class=\\"btn btn-secondary voltar-topo\\" href=\\"javascript:void(0)\\" onclick=\\"tplRelCal_irParaSecao_(\'tplRelCal_topoManual\'); return false;\\">↑ Topo</a>\\n</div>";\n\n\nfunction tplRelCal_abrirManual_() {\n  const viewModulo = document.getElementById(\'tplRelCal_viewModulo\');\n  const viewManual = document.getElementById(\'tplRelCal_viewManual\');\n  if (viewModulo) viewModulo.style.display = \'none\';\n  if (viewManual) viewManual.style.display = \'\';\n}\n\nfunction tplRelCal_voltarDoManual_() {\n  const viewModulo = document.getElementById(\'tplRelCal_viewModulo\');\n  const viewManual = document.getElementById(\'tplRelCal_viewManual\');\n  if (viewManual) viewManual.style.display = \'none\';\n  if (viewModulo) viewModulo.style.display = \'\';\n}\n\n\nfunction tplRelCal_irParaSecao_(id) {\n  var el = document.getElementById(id);\n  if (el && el.scrollIntoView) el.scrollIntoView({ behavior: \'smooth\', block: \'start\' });\n}\n<\/script>';function RelCal_obterConteudoModulo(){return RELCAL_CONTEUDO_MODULO}
